  sealed class Source {public string Id,Name;public override string ToString(){return Name;}}
  void Reload(string selected=null){loading=true;list.Items.Clear();foreach(var n in document.Stages)list.Items.Add(n);list.DisplayMember="Name";list.SelectedIndex=document.Stages.Count==0?-1:Math.Max(0,document.Stages.FindIndex(n=>n.Id==selected));rpm.Value=(decimal)document.InputRpm;torque.Value=(decimal)document.InputTorque;loading=false;SelectStage();}
  void SelectStage(){if(loading)return;if(!CaptureStage()){loading=true;list.SelectedItem=editingStage;loading=false;return;}var n=list.SelectedItem as TrainStage;if(editor!=null){editor.WorkspaceApproveClose();edit.Controls.Remove(editor);editor.Close();editor.Dispose();editor=null;}if(n==null)return;loading=true;parent.Items.Clear();secondParent.Items.Clear();parent.Items.Add(new Source{Name="Двигатель"});secondParent.Items.Add(new Source{Name="Нет"});foreach(var x in document.Stages.Where(x=>x.Id!=n.Id)){parent.Items.Add(new Source{Id=x.Id,Name=x.Name});secondParent.Items.Add(new Source{Id=x.Id,Name=x.Name});}parent.SelectedIndex=0;secondParent.SelectedIndex=0;for(int i=1;i<parent.Items.Count;i++)if(((Source)parent.Items[i]).Id==n.Parent)parent.SelectedIndex=i;for(int i=1;i<secondParent.Items.Count;i++)if(((Source)secondParent.Items[i]).Id==n.SecondParent)secondParent.SelectedIndex=i;share.Value=(decimal)n.PowerShare;secondShare.Value=(decimal)n.SecondPowerShare;loading=false;editingStage=n;editor=new MainForm();editor.TopLevel=false;editor.FormBorderStyle=FormBorderStyle.None;editor.Dock=DockStyle.Fill;editor.MinimumSize=Size.Empty;edit.Controls.Add(editor);editor.ConfigureForTrain(n.Parameters,p=>{n.Parameters=p;n.Name=TransmissionCatalog.All[p.Kind].Name;dirty=true;list.Refresh();Calculate();});editor.Show();}
  void CommitConnections(){if(loading)return;var n=list.SelectedItem as TrainStage;if(n==null)return;n.Parent=parent.SelectedItem==null?null:((Source)parent.SelectedItem).Id;n.SecondParent=secondParent.SelectedItem==null?null:((Source)secondParent.SelectedItem).Id;n.PowerShare=(double)share.Value;n.SecondPowerShare=(double)secondShare.Value;dirty=true;}
  bool CaptureStage(){if(editor==null||editingStage==null)return true;if(!editor.StageCanClose){status.Text="Дождитесь экспорта ступени или отмените его.";return false;}if(!document.Stages.Contains(editingStage))return true;Parameters value;if(!editor.TryStageParameters(out value)){status.Text="Параметры ступени некорректны; исправьте их перед расчётом/сохранением.";return false;}if(ReleaseSupport.Serialize(editingStage.Parameters)!=ReleaseSupport.Serialize(value)){editingStage.Parameters=value;editingStage.Name=TransmissionCatalog.All[value.Kind].Name;dirty=true;}return true;}
  void Calculate(){if(!CaptureStage()){solution=null;return;}timer.Stop();solution=TrainSolver.Solve(document);if(!solution.Valid){status.Text=string.Join("; ",solution.Errors);return;}phase=0;viewer.SetResult(solution.Scene,true);table.Rows.Clear();foreach(var s in solution.States.Values){bool linear=s.Result.Engineering!=null&&s.Result.Engineering.Linear;table.Rows.Add(s.Name,Engine.F(s.InputRpm),Engine.F(linear?s.LinearSpeed:s.OutputRpm),Engine.F(linear?s.OutputForce:s.OutputTorque),Engine.F(s.Efficiency),Engine.F(s.OutputPower));}var leaves=solution.States.Values.Where(s=>!document.Stages.Any(n=>n.Parent==s.Id||n.SecondParent==s.Id)).ToList();status.Text=string.Join("; ",leaves.Select(s=>s.Name+": "+(s.Result.Engineering!=null&&s.Result.Engineering.Linear?Engine.F(s.LinearSpeed)+" мм/с":Math.Abs(s.OutputGain)<1e-12?"выход неподвижен":"суммарное i="+Engine.F(1/Math.Abs(s.OutputGain))+", "+Engine.F(s.OutputRpm)+" об/мин")))+"\nМасса модели ≈ "+Engine.F(solution.Mass)+" кг. Моменты теоретические, допустимые нагрузки не подтверждены.";}
  void Save(){if(!CaptureStage())return;using(var d=new SaveFileDialog{Filter="Граф GearLab|*.train.json",FileName=path??"Редуктор.train.json"})if(d.ShowDialog(this)==DialogResult.OK){document.Save(d.FileName);path=d.FileName;dirty=false;}}
  void Open(){if(!WorkspaceCanClose())return;using(var d=new OpenFileDialog{Filter="Граф GearLab|*.train.json"})if(d.ShowDialog(this)==DialogResult.OK)try{document=TransmissionTrain.Read(d.FileName);path=d.FileName;dirty=false;Reload();Calculate();}catch(Exception ex){status.Text=ex.Message;}}
  async void Export(){if(busy)return;Calculate();if(solution==null||!solution.Valid)return;using(var d=new SaveFileDialog{Filter="STEP|*.step"})if(d.ShowDialog(this)==DialogResult.OK){string target=d.FileName,temp=target+"."+Guid.NewGuid().ToString("N")+".tmp";busy=true;try{var model=solution.Scene.Model;await System.Threading.Tasks.Task.Factory.StartNew(()=>TransmissionExport.Write(model,temp,kernel));if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);status.Text="STEP сохранён: "+target;}catch(Exception ex){status.Text=ex.GetBaseException().Message;}finally{busy=false;if(File.Exists(temp))File.Delete(temp);}}}
